<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff Management - C-Net Library</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#f5f7fb;margin:0;color:#1f2937}.wrap{max-width:1350px;margin:28px auto;padding:0 18px}.top,.inline{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.top{justify-content:space-between;margin-bottom:18px}.grid{display:grid;grid-template-columns:360px 1fr;gap:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:18px;margin-bottom:18px}.field{margin-bottom:10px}input,select,textarea{width:100%;padding:8px;border:1px solid #d1d5db;border-radius:8px;margin-top:4px}.btn{border:0;border-radius:8px;padding:9px 12px;background:#111827;color:#fff;text-decoration:none;cursor:pointer;font-weight:700}.alt{background:#0f766e}.danger{background:#b91c1c}.muted{color:#6b7280;font-size:12px}.staff{border:1px solid #e5e7eb;border-radius:12px;padding:14px;margin-bottom:12px}.editgrid{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:8px}.payroll{display:grid;grid-template-columns:70px 90px 100px 100px 110px 120px 140px auto;gap:6px;align-items:end}.notice{padding:10px;border-radius:9px;margin-bottom:12px}.ok{background:#f0fdf4}.err{background:#fef2f2}@media(max-width:1050px){.grid{grid-template-columns:1fr}.editgrid{grid-template-columns:repeat(2,1fr)}.payroll{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.editgrid,.payroll{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><div><h1 style="margin:0">HR / Staff Management</h1><div class="muted">Create, edit, activate/inactivate and safely delete staff while preserving attendance/payroll history.</div></div><div class="inline"><a class="btn" href="{{ route('admin.expenses.index') }}">Cashbook</a><a class="btn" href="{{ route('admin.dashboard') }}">Dashboard</a></div></div>@if(session('success'))<div class="notice ok">{{ session('success') }}</div>@endif @if($errors->any())<div class="notice err"><ul style="margin:0;padding-left:18px">@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul></div>@endif<div class="grid"><div><div class="card"><h2 style="margin-top:0">Add Staff</h2><form method="POST" action="{{ route('admin.staff.store') }}">@csrf<div class="field"><label>Name<input name="name" required></label></div><div class="field"><label>Role<input name="role" required value="staff"></label></div><div class="field"><label>Branch<select name="branch_id" required>@foreach($branches as $branch)<option value="{{ $branch->id }}">{{ $branch->name }}</option>@endforeach</select></label></div><div class="field"><label>Mobile<input name="mobile"></label></div><div class="field"><label>Email<input type="email" name="email"></label></div><div class="field"><label>Joining Date<input type="date" name="joining_date"></label></div><div class="field"><label>Monthly Salary<input type="number" min="0" step="0.01" name="monthly_salary" value="0"></label></div><button class="btn alt">Create Staff</button></form></div><div class="card"><h2 style="margin-top:0">Pending Leaves</h2>@forelse($pendingLeaves as $leave)<div style="padding:10px 0;border-bottom:1px solid #eee"><strong>{{ $leave->staff?->name }}</strong><div class="muted">{{ $leave->from_date?->format('d M Y') }} - {{ $leave->to_date?->format('d M Y') }}</div><form method="POST" action="{{ route('admin.staff.leaves.update',$leave) }}" class="inline" style="margin-top:6px">@csrf @method('PATCH')<select name="status" style="max-width:130px"><option value="approved">Approve</option><option value="rejected">Reject</option></select><input name="admin_remarks" placeholder="Remarks" style="max-width:180px"><button class="btn">Save</button></form></div>@empty<div class="muted">No pending leave requests.</div>@endforelse</div></div><div>@forelse($staff as $member)<div class="staff"><div class="top" style="margin-bottom:8px"><div><strong>{{ $member->name }}</strong> <span class="muted">{{ $member->staff_code }}</span><div class="muted">Attendance: {{ $member->attendances_count }} · Leaves: {{ $member->leaves_count }} · Payrolls: {{ $member->payrolls_count }}</div></div><strong>{{ ucfirst($member->status) }}</strong></div><form method="POST" action="{{ route('admin.staff.update',$member) }}">@csrf @method('PATCH')<div class="editgrid"><input name="name" value="{{ $member->name }}" required><input name="role" value="{{ $member->role }}" required><select name="branch_id">@foreach($branches as $branch)<option value="{{ $branch->id }}" @selected((int)$member->branch_id===$branch->id)>{{ $branch->name }}</option>@endforeach</select><select name="status"><option value="active" @selected($member->status==='active')>Active</option><option value="inactive" @selected($member->status==='inactive')>Inactive</option></select><input name="mobile" value="{{ $member->mobile }}" placeholder="Mobile"><input type="email" name="email" value="{{ $member->email }}" placeholder="Email"><input type="date" name="joining_date" value="{{ $member->joining_date?->format('Y-m-d') }}"><input type="number" min="0" step="0.01" name="monthly_salary" value="{{ $member->monthly_salary }}" required></div><button class="btn alt" style="margin-top:8px">Save Staff Edit</button></form><div class="inline" style="margin-top:10px"><form method="POST" action="{{ route('admin.staff.attendance',$member) }}" class="inline">@csrf<select name="status"><option value="present">Present</option><option value="absent">Absent</option><option value="half_day">Half day</option><option value="leave">Leave</option></select><select name="staff_shift_id"><option value="">No shift</option>@foreach($shifts as $shift)<option value="{{ $shift->id }}">{{ $shift->name }}</option>@endforeach</select><button class="btn">Mark Attendance</button></form><form method="POST" action="{{ route('admin.staff.destroy',$member) }}" onsubmit="return confirm('Delete this staff? History will cause safe Inactive instead.')">@csrf @method('DELETE')<button class="btn danger">Delete / Safe Inactive</button></form></div><form class="payroll" method="POST" action="{{ route('admin.staff.payroll',$member) }}" style="margin-top:12px">@csrf<label>Month<input type="number" name="month" min="1" max="12" value="{{ now()->month }}" required></label><label>Year<input type="number" name="year" value="{{ now()->year }}" required></label><label>Allowance<input type="number" name="allowances" min="0" step="0.01" value="0"></label><label>Deduction<input type="number" name="deductions" min="0" step="0.01" value="0"></label><label>Status<select name="status"><option value="pending">Pending</option><option value="paid">Paid</option></select></label><label>Mode<select name="payment_mode"><option value="">Select</option><option value="cash">Cash</option><option value="upi">UPI</option><option value="card">Card</option><option value="bank_transfer">Bank</option><option value="other">Other</option></select></label><label>Txn Ref<input name="transaction_ref"></label><button class="btn">Save Payroll</button></form></div>@empty<div class="card muted">No staff records.</div>@endforelse<div>{{ $staff->links() }}</div><div class="card"><h2 style="margin-top:0">Today's Attendance</h2>@forelse($todayAttendance as $row)<div>{{ $row->staff?->name }} — {{ ucfirst(str_replace('_',' ',$row->status)) }} <span class="muted">{{ $row->check_in?->format('h:i A') ?? '—' }}</span></div>@empty<div class="muted">No attendance marked today.</div>@endforelse</div><div class="card"><h2 style="margin-top:0">Recent Payroll</h2>@forelse($recentPayrolls as $p)<div>{{ $p->staff?->name }} — {{ str_pad($p->month,2,'0',STR_PAD_LEFT) }}/{{ $p->year }} — ₹{{ number_format((float)$p->net_salary,2) }} — {{ ucfirst($p->status) }}</div>@empty<div class="muted">No payroll records.</div>@endforelse</div></div></div></div></body></html>